using System.Collections;using UnityEngine;using UnityEngine.AI;using NWD.Combat;using NWD.Core;
namespace NWD.Enemies { public enum InfectedState{Idle,InvestigateNoise,Chase,Attack,Stagger,Dead}
 [RequireComponent(typeof(NavMeshAgent),typeof(HealthComponent))] public sealed class InfectedBrain:MonoBehaviour { public InfectedState State{get;private set;} public Transform target;NavMeshAgent agent;HealthComponent health;void Awake(){agent=GetComponent<NavMeshAgent>();health=GetComponent<HealthComponent>();health.Died+=()=>{State=InfectedState.Dead;agent.enabled=false;};}void OnEnable()=>NoiseSystem.Emitted+=Hear;void OnDisable()=>NoiseSystem.Emitted-=Hear;void Hear(NoiseEvent n){if(State==InfectedState.Dead||Vector3.Distance(transform.position,n.Position)>n.Radius)return;State=InfectedState.InvestigateNoise;if(agent.isOnNavMesh)agent.SetDestination(n.Position);} public void Tick(){if(target&&State!=InfectedState.Dead){State=Vector3.Distance(transform.position,target.position)<2?InfectedState.Attack:InfectedState.Chase;if(agent.isOnNavMesh)agent.SetDestination(target.position);}} }
 public sealed class HordeDirector:MonoBehaviour { public float pressure,noiseAccumulated,difficulty=1;public int alive,activeObjectives;public int CalculateBudget()=>Mathf.Max(0,Mathf.FloorToInt((pressure+noiseAccumulated*.5f+activeObjectives)*difficulty)-alive);public IEnumerator Run(float cooldown){while(enabled){yield return new WaitForSeconds(cooldown);/* bounded scheduled evaluation; spawn volumes validate camera visibility and NavMesh before spawning */}} }
 public interface IPoolable { void OnSpawned();void OnDespawned(); }
}
